def clean_domain(text):
    """Dominio escrito o pegado como direccion (https://www.mitienda.com/tienda): solo el nombre."""
    d = re.sub(r"^[A-Za-z][A-Za-z0-9+.-]*://", "", text.strip())
    return re.split(r"[/?#:\s]", d, maxsplit=1)[0].rstrip(".")


